constructor(options: TxBuilderOptions = {}) {
		const { params, fetcher, submitter, isHydra = false, verbose = false, errorLogger = false } = options

		this._fetcher = fetcher
		this._submitter = submitter
		this._isHydra = isHydra
		this._verbose = verbose
		this._errorLogger = errorLogger

		if (params) {
			this.updateProtocolParams(params)
		}
		this._txBuilder = TxBuilder.getTxBuilder(this._protocolParams)
	}

constructor(options: InitHydraBridgeOptions) {
		this._verbose = options.verbose || false
		if ('connector' in options) {
			this.connector = options.connector
		} else {
			this.connector = new WebsocketConnector({
				websocketUrl: options.url
			})
		}
		this._eventEmitter = this.connector.eventEmitter
		this._eventEmitter.on('onConnected', () => {
			this.querySnapshotUtxo()
		})
	}

